import{createHostNitro}from"#internal/nitro/host/create-host-nitro.js";import{createHostSpec}from"#internal/nitro/host/host-spec.js";import{prepareDevelopmentApplicationHost}from"#internal/nitro/host/prepare-application-host.js";import{buildDevelopmentHostCandidate}from"#internal/nitro/host/dev-host-candidate.js";async function prepareDevelopmentBuild(e){return await prepareDevelopmentApplicationHost(e.appRoot,{changedPaths:e.changedPaths,developmentExtensions:e.developmentExtensions,previousExtensions:e.previousExtensions,workspace:e.workspace})}async function buildDevelopmentHost(e){let t=await createHostNitro(createHostSpec(e,{kind:`development`},{buildDir:e.workspace.nitroBuildDir,outputDir:e.workspace.nitroOutputDir}));return await buildDevelopmentHostCandidate({host:e,nitro:t})}export{buildDevelopmentHost,prepareDevelopmentBuild};